import type { Metadata } from "next";
import { getSiteUrl } from "@/lib/site-url";

/** Public origin used for canonical URLs, sitemaps, and structured data. */
export const SITE_URL = getSiteUrl() || "https://drawtiq.netlify.app";

export const SITE_NAME = "Drawtiq";

/** Generated by app/opengraph-image.tsx. */
export const SHARE_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "Drawtiq — independent design studio for digital products and brands",
};

export function absoluteUrl(path = "/") {
  return new URL(path, SITE_URL).toString();
}

function plainTitle(title: Metadata["title"]): string | undefined {
  if (!title) return undefined;
  if (typeof title === "string") return title;
  if ("absolute" in title && title.absolute) return title.absolute;
  if ("default" in title && title.default) return title.default;
  return undefined;
}

/**
 * Complete a page's metadata: Open Graph and Twitter tags that match the
 * page's own title, description, and canonical URL (Next.js replaces, rather
 * than merges, the root openGraph object per page, so every page must set it).
 * The share image comes from app/opengraph-image.tsx.
 */
export function pageSeo(
  metadata: Metadata,
  options: { type?: "website" | "article"; publishedTime?: string | null; modifiedTime?: string | null } = {}
): Metadata {
  const canonical = metadata.alternates?.canonical;
  const path = typeof canonical === "string" ? canonical : "/";
  const title = plainTitle(metadata.title);
  const socialTitle = title && !title.includes(SITE_NAME) ? `${title} | ${SITE_NAME}` : title;
  const description = metadata.description ?? undefined;

  return {
    ...metadata,
    openGraph: {
      type: options.type ?? "website",
      siteName: SITE_NAME,
      locale: "en_US",
      url: path,
      title: socialTitle,
      description,
      images: [SHARE_IMAGE],
      ...(options.type === "article" && options.publishedTime
        ? { publishedTime: options.publishedTime, modifiedTime: options.modifiedTime ?? undefined }
        : {}),
      ...metadata.openGraph,
    },
    twitter: {
      card: "summary_large_image",
      title: socialTitle,
      description,
      images: [SHARE_IMAGE.url],
      ...metadata.twitter,
    },
  };
}
